 before=load(i);p=ROOT/'proposed'/'items'/f'{i}.md';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s)
 diff=''.join(difflib.unified_diff(before.splitlines(True),s.splitlines(True),fromfile=f'items/{i}.md',tofile=f'items/{i}.md'))
 (ROOT/f'{i}.diff').write_text(diff)
 CHANGES.append({'id':i,'before_raw_sha256':hashlib.sha256(before.encode()).hexdigest(),'proposed_raw_sha256':hashlib.sha256(s.encode()).hexdigest(),'proposal':str(p),'diff':str(ROOT/f'{i}.diff'),'description':description})
